// ─── TransactionSynchronization: callback after commit ───
@Transactional
public void transferWithCallback(String from, String to, BigDecimal amount) {
    accountRepo.debit(from, amount);
    accountRepo.credit(to, amount);

    // Register callback — fires ONLY after this TX commits
    TransactionSynchronizationManager.registerSynchronization(
        new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                // Safe: TX is committed. Send notification.
                notificationService.send(from, "Transfer of Rs." + amount + " completed");
            }

            @Override
            public void afterCompletion(int status) {
                if (status == STATUS_ROLLED_BACK) {
                    log.warn("TX rolled back — notification NOT sent");
                }
            }
        });
}

// ─── TransactionTemplate: batch with per-chunk commit ───
public int batchProcess(List<Trade> trades) {
    int total = 0;
    for (int i = 0; i < trades.size(); i += 500) {
        List<Trade> chunk = trades.subList(i, Math.min(i + 500, trades.size()));
        Integer count = txTemplate.execute(status -> {
            chunk.forEach(t -> { t.settle(); tradeRepo.save(t); });
            return chunk.size();
        });
        total += count;  // each chunk committed independently
    }
    return total;
}
